INSERT INTO `currency_types_locale` (`ID`, `locale`, `Name_lang`, `Description_lang`, `VerifiedBuild`) VALUES
(3378, 'itIT', 'Manaflusso di Albaluce', 'Il Manaflusso di Albaluce carica il Catalizzatore e gli permette di infondere incredibile potere nelle armature. Si accumula lentamente ogni due settimane.', 65893),
(3028, 'itIT', 'Chiave dello Scrigno Ripristinata', 'Si ottiene combinando 100 Schegge di Chiave dello Scrigno recuperate all\'aperto. Apre uno Scrigno Fruttuoso all\'interno di una Scorribanda Fruttuosa.', 65893),
(3291, 'itIT', 'Emblema Etereo Dorato', 'Si usa per potenziare l\'equipaggiamento Eroe e Mito durante la Stagione 3 di The War Within dai livelli 147 in poi. Si ottiene dalle attività seguenti:\n\n- Manaforgia Omega Mitica\n- Spedizioni Mitiche+ da +7 in poi\n- Scorta Dorata della Scorribanda (Grado 11)\n- Bottino della Scorribanda (Gradi 8 e superiori)', 65893),
(3290, 'itIT', 'Emblema Etereo Dorato', 'Si usa per potenziare l\'equipaggiamento Eroe e Mito durante la Stagione 3 di The War Within dai livelli 147 in poi. Si ottiene dalle attività seguenti:\n\n- Manaforgia Omega Mitica\n- Spedizioni Mitiche+ da +7 in poi\n- Scorta Dorata della Scorribanda (Grado 11)\n- Bottino della Scorribanda (Gradi 8 e superiori)', 65893),
(3289, 'itIT', 'Emblema Etereo Runico', 'Si usa per potenziare l\'equipaggiamento Campione ed Eroe durante la Stagione 3 di The War Within fino ai livelli 134-144. Si ottiene dalle attività seguenti:\n\n- Manaforgia Omega Eroica\n- Spedizioni Mitiche+ da +2 a +6\n- Scorribande (Gradi 8-11)\n- Bottino della Scorribanda (Gradi 6 e 7)', 65893),
(3288, 'itIT', 'Emblema Etereo Runico', 'Si usa per potenziare l\'equipaggiamento Campione ed Eroe durante la Stagione 3 di The War Within fino ai livelli 134-144. Si ottiene dalle attività seguenti:\n\n- Manaforgia Omega Eroica\n- Spedizioni Mitiche+ da +2 a +6\n- Scorribande (Gradi 8-11)\n- Bottino della Scorribanda (Gradi 6 e 7)', 65893),
(3287, 'itIT', 'Emblema Etereo Intagliato', 'Si usa per potenziare l\'equipaggiamento Veterano e Campione durante la Stagione 3 di The War Within fino ai livelli 121-131. Si ottiene dalle attività seguenti:\n\n- Eventi esterni settimanali\n- Manaforgia Omega Normale\n- Spedizioni stagionali Mitiche\n- Scorribande (Gradi 6 e 7)\n- Bottino della Scorribanda (Gradi 4 e 5)', 65893),
(3286, 'itIT', 'Emblema Etereo Intagliato', 'Si usa per potenziare l\'equipaggiamento Veterano e Campione durante la Stagione 3 di The War Within fino ai livelli 121-131. Si ottiene dalle attività seguenti:\n\n- Eventi esterni settimanali\n- Manaforgia Omega Normale\n- Spedizioni stagionali Mitiche\n- Scorribande (Gradi 6 e 7)\n- Bottino della Scorribanda (Gradi 4 e 5)', 65893),
(3285, 'itIT', 'Emblema Etereo Logoro', 'Si usa per potenziare l\'equipaggiamento Avventuriero e Veterano durante la Stagione 3 di The War Within fino ai livelli 108-118. Si ottiene dalle attività seguenti:\n\n- Eventi esterni ripetibili\n- Manaforgia Omega Ricerca delle Incursioni\n- Spedizioni stagionali Eroiche\n- Scorribande (Gradi 1-5)', 65893),
(3284, 'itIT', 'Emblema Etereo Logoro', 'Si usa per potenziare l\'equipaggiamento Avventuriero e Veterano durante la Stagione 3 di The War Within fino ai livelli 108-118. Si ottiene dalle attività seguenti:\n\n- Eventi esterni ripetibili\n- Manaforgia Omega Ricerca delle Incursioni\n- Spedizioni stagionali Eroiche\n- Scorribande (Gradi 1-5)', 65893),
(3388, 'itIT', 'Fama - Singolarità', '[DNT]', 65893),
(3310, 'itIT', 'Schegge di Chiave dello Scrigno', 'Ottenibile dai tesori, dalle missioni mondiali e dagli eventi esterni in tutte le zone di Midnight. Entrare in una Scorribanda combina 100 Schegge in una Chiave dello Scrigno Ripristinata.', 65893),
(3400, 'itIT', 'Campione di Vuoto Incontaminato', 'Campioni utilizzabili per approfondire la ricerca sul Vuoto. Questi possono essere usati alla Console di Ricerca presso la Cresta Ululante, nella Tempesta del Vuoto.', 65893);
