INSERT INTO `mount_locale` (`ID`, `locale`, `Name_lang`, `SourceText_lang`, `Description_lang`, `VerifiedBuild`) VALUES
(2969, 'itIT', 'Dragofalco Spettrale Rapido', '|cFFFFD200Lascito|r', 'Anche i morti hanno bisogno di volare rapidamente ogni tanto.', 65893),
(2607, 'itIT', 'Ceneri di Belo\'ren', '|cFFFFD200Bottino: |rScoccare della Mezzanotte|n|cFFFFD200Luogo: |rMarcia su Quel\'Danas (Mitica)', 'Belo\'ren, della prole di Al\'ar, è stato portato sull\'Isola di Quel\'Danas e cresciuto per difendere Pozzo Solare da qualsiasi minaccia, anche a costo di morire. Tuttavia, si dice che la morte non riuscirà mai a prenderselo.', 65893),
(2794, 'itIT', 'Faucertola Malvagia', '|cFFFFD200PvP:|r Midnight: Stagione 1|nRicompensa stagionale di arene e campi di battaglia classificati.', 'Queste creature si aggirano furtivamente sul campo di battaglia e si arrampicano sugli ostacoli, pronte a dare fastidio all\'Orda.', 65893),
(2793, 'itIT', 'Faucertola Malvagia', '|cFFFFD200PvP:|r Midnight: Stagione 1|nRicompensa stagionale di arene e campi di battaglia classificati.', 'Queste creature si aggirano furtivamente sul campo di battaglia e si arrampicano sugli ostacoli, pronte a dare fastidio all\'Alleanza.', 65893),
(430, 'itIT', 'Zampalunga Rapido', '|cFFFFD200Mercante: |rMercante di Nobiluova|n|cFFFFD200Zona: |rDurotar, Boschi di Cantoeterno (Crociata Infuocata), Mulgore, Radure di Tirisfal, Isola Brumazzurra, |nDun Morogh, Foresta di Elwynn, Teldrassil|n|cFFFFD200Costo: |r500|Hitem:44791|h|TINTERFACE\\ICONS\\ACHIEVEMENT_NOBLEGARDEN_CHOCOLATE_EGG.BLP:0|t|h|n', 'Le gioie della Festa di Nobiluova sono più piacevoli se celebrate con questo leale, amorevole ed estremamente colorato scherzo della natura.', 65893),
(161, 'itIT', 'Zampalesta Viola Rapido', '|cFFFFD200Mercante: |rWinaestra|n|cFFFFD200Zona: |rBoschi di Cantoeterno (Crociata Infuocata)|n|cFFFFD200Costo: |r10|TINTERFACE\\MONEYFRAME\\UI-GOLDICON.BLP:0|t', '\"Il loro piumaggio è uno dei più vistosi nel mondo animale. Del resto, la scaltrezza serve agli uccelli. Cioè... agli altri uccelli.\"\" - Viera Soffiasole', 65893),
(160, 'itIT', 'Zampalesta Verde Rapido', '|cFFFFD200Mercante: |rWinaestra|n|cFFFFD200Zona: |rBoschi di Cantoeterno (Crociata Infuocata)|n|cFFFFD200Costo: |r10|TINTERFACE\\MONEYFRAME\\UI-GOLDICON.BLP:0|t', '\"Il loro piumaggio è uno dei più vistosi nel mondo animale. Del resto, la scaltrezza serve agli uccelli. Cioè... agli altri uccelli.\"\" - Viera Soffiasole', 65893),
(159, 'itIT', 'Zampalesta Nero', '|cFFFFD200Mercante: |rWinaestra|n|cFFFFD200Zona: |rBoschi di Cantoeterno (Crociata Infuocata)|n|cFFFFD200Costo: |r1|TINTERFACE\\MONEYFRAME\\UI-GOLDICON.BLP:0|t', '\"Alcuni dei nostri compatrioti preferiscono i cavalli, ma gli zampalesta sono il vero simbolo di Lunargenta.\" - Winaestra', 65893),
(158, 'itIT', 'Zampalesta Blu', '|cFFFFD200Mercante: |rWinaestra|n|cFFFFD200Zona: |rBoschi di Cantoeterno (Crociata Infuocata)|n|cFFFFD200Costo: |r1|TINTERFACE\\MONEYFRAME\\UI-GOLDICON.BLP:0|t', '\"Alcuni dei nostri compatrioti preferiscono i cavalli, ma gli zampalesta sono il vero simbolo di Lunargenta.\" - Winaestra', 65893),
(157, 'itIT', 'Zampalesta Viola', '|cFFFFD200Mercante: |rWinaestra|n|cFFFFD200Zona: |rBoschi di Cantoeterno (Crociata Infuocata)|n|cFFFFD200Costo: |r1|TINTERFACE\\MONEYFRAME\\UI-GOLDICON.BLP:0|t', '\"Alcuni dei nostri compatrioti preferiscono i cavalli, ma gli zampalesta sono il vero simbolo di Lunargenta.\" - Winaestra', 65893),
(152, 'itIT', 'Zampalesta Rosso', '|cFFFFD200Mercante: |rWinaestra|n|cFFFFD200Zona: |rBoschi di Cantoeterno (Crociata Infuocata)|n|cFFFFD200Costo: |r1|TINTERFACE\\MONEYFRAME\\UI-GOLDICON.BLP:0|t', '\"Alcuni dei nostri compatrioti preferiscono i cavalli, ma gli zampalesta sono il vero simbolo di Lunargenta.\" - Winaestra', 65893),
(146, 'itIT', 'Zampalesta Rosa Rapido', '|cFFFFD200Mercante: |rWinaestra|n|cFFFFD200Zona: |rBoschi di Cantoeterno (Crociata Infuocata)|n|cFFFFD200Costo: |r10|TINTERFACE\\MONEYFRAME\\UI-GOLDICON.BLP:0|t', '\"Il loro piumaggio è uno dei più vistosi nel mondo animale. Del resto, la scaltrezza serve agli uccelli. Cioè... agli altri uccelli.\" - Viera Soffiasole', 65893);
