INSERT INTO `trait_definition_locale` (`ID`, `locale`, `OverrideName_lang`, `OverrideSubtext_lang`, `OverrideDescription_lang`, `VerifiedBuild`) VALUES
(136690, 'itIT', '', '', '+$ev1 $en1 quando si creano Attrezzi e Accessori delle professioni.', 65893),
(136518, 'itIT', '', '', '- +$ev1 $en1 quando si tagliano Olivine di Harandar.|n|n- Riduce il costo del $ev2% quando ci si concentra sulle ricette di Olivina Potente.', 65893),
(136496, 'itIT', '', '', '- +$ev1 $en1 quando si tagliano Lapislazzuli degli Amani.|n|n- Riduce il costo del $ev2% quando ci si concentra sulle ricette di Lapislazzuli Lucido.', 65893),
(136464, 'itIT', '', '', '- +$ev1 $en1 quando si tagliano Ametiste Tenebrose.|n|n- Riduce il costo del $ev2% quando ci si concentra sulle ricette di Ametista Austera.', 65893),
(136442, 'itIT', '', '', '- +$ev1 $en1 quando si tagliano Granati Rosso Sangue.|n|n- Riduce il costo del $ev2% quando ci si concentra sulle ricette di Granato Glorioso.', 65893),
(107539, 'itIT', '', '', '', 65893),
(136642, 'itIT', 'Lavorazione Proficua', '', 'Specializzati nella generazione di materiali e gemme, provvedendo ai reagenti di cui avete bisogno tu e gli altri artigiani.', 65893),
(136641, 'itIT', 'Professionista della Prospezione', '', '', 65893),
(136640, 'itIT', 'Consumatore di Rame', '', '', 65893),
(136639, 'itIT', 'Bagno di Stagno', '', '', 65893),
(136638, 'itIT', 'Ricerca dell\'Argento', '', '', 65893),
(136637, 'itIT', 'Frantumazione del Torio', '', '', 65893),
(136636, 'itIT', 'Esperto della Frantumazione', '', '', 65893),
(136635, 'itIT', 'Manifattura di Materiali', '', '', 65893),
(136634, 'itIT', 'Facoltativo e Funzionale', '', '', 65893),
(136633, 'itIT', 'Basi delle Basi', '', '', 65893),
(136632, 'itIT', 'Lavorazione Proficua', '', 'Concentra gli sforzi sulla produzione di materiali, ottenendo +$ev1 $en1 quando si pratica la Prospezione, Frantumazione e la creazione di Reagenti per ogni punto in questa specializzazione.', 65893),
(136631, 'itIT', '', '', '+$ev1 $en1 quando si pratica la Prospezione, Frantumazione e la creazione di Reagenti.', 65893),
(136630, 'itIT', '', '', '+$ev1 $en1 quando si pratica la Prospezione, Frantumazione e la creazione di Reagenti.', 65893),
(136629, 'itIT', '', '', 'Inizia il tuo viaggio nelle tecniche di lavorazione, apprendendo una sottospecializzazione a tua scelta.', 65893),
(136628, 'itIT', '', '', '+$EV1 $EN1 quando si creano reagenti.', 65893),
(136627, 'itIT', '', '', 'Migliora il tuo repertorio di tecniche della lavorazione, apprendendo una sottospecializzazione a tua scelta.', 65893),
(136626, 'itIT', '', '', '+$ev1 $en1 quando si pratica la Prospezione, Frantumazione e la creazione di Reagenti.', 65893),
(136625, 'itIT', '', '', '- Padroneggia le basi di una Lavorazione Perfetta, apprendendo l\'ultima sottospecializzazione.|n|n- La velocità di creazione e di riciclaggio è aumentata del $ev1%. |n|n- Riduce il costo di Concentrazione del $ev2% quando ci si concentra sui Reagenti e Riciclaggio.', 65893),
(136624, 'itIT', 'Professionista della Prospezione', '', 'Padroneggia l\'arte di setacciare i minerali in cerca di gemme preziose, ottenendo +$ev1 $en1 quando esegui la Prospezione per ogni punto in questa specializzazione.', 65893),
(136623, 'itIT', '', '', 'Avviati sulla strada della Prospezione, apprendendo una sottospecializzazione a tua scelta.', 65893),
(136622, 'itIT', '', '', '+$ev1 $en1 quando si pratica la Prospezione.', 65893),
(136621, 'itIT', '', '', 'Allarga i tuoi orizzonti includendo un altro minerale, apprendendo una sottospecializzazione a tua scelta.', 65893),
(136620, 'itIT', '', '', '+$ev1 $en1 quando si pratica la Prospezione.', 65893),
(136619, 'itIT', '', '', 'Concentrati su un nuovo tipo di minerale per la Prospezione, apprendendo una sottospecializzazione a tua scelta.', 65893),
(136618, 'itIT', '', '', '+$ev1 $en1 quando si pratica la Prospezione.', 65893),
(136617, 'itIT', '', '', '- Comincia a padroneggiare la versione finale della Prospezione, apprendendo una sottospecializzazione a tua scelta.|n|n- La velocità di Prospezione è aumentata del $ev1%.|n|n- Quando si trova una gemma con la Prospezione, c\'è anche la possibilità di trovare una gemma aggiuntiva.', 65893),
(136616, 'itIT', 'Consumatore di Rame', '', 'Comprendi gli schemi e le complessità del Rame Rifulgente, apprendendo come trovare i Diamanti di Cantoeterno nascosti durante la Prospezione.', 65893),
(136609, 'itIT', '', '', 'Fornisce una probabilità estremamente rara di trovare un Diamante di Cantoeterno quando si esegue la Prospezione sul Rame Rifulgente.', 65893),
(136608, 'itIT', 'Bagno di Stagno', '', 'Rifiutati di ignorare l\'importanza del comprendere lo Stagno Ombrale, ottenendo la capacità di trovare occasionalmente Diamanti di Cantoeterno durante la Prospezione.', 65893),
(136601, 'itIT', '', '', 'Fornisce una probabilità molto rara di trovare un Diamante di Cantoeterno durante la Prospezione dello Stagno Ombrale.', 65893),
(136600, 'itIT', 'Ricerca dell\'Argento', '', 'Preparati a splendere mentre lavori con l\'Argento Brillante, ottenendo la capacità di trovare Diamanti di Cantoeterno durante la Prospezione.', 65893),
(136593, 'itIT', '', '', 'Fornisce una probabilità molto rara di trovare un Diamante di Cantoeterno con la Prospezione dell\'Argento Brillante.', 65893),
(136592, 'itIT', 'Frantumazione del Torio', '', 'Scopri i segnali che indicano la presenza di gemme nascoste nel Torio Abbagliante, potenziando la capacità di trovare Diamanti di Cantoeterno durante la Prospezione.', 65893),
(136585, 'itIT', '', '', 'Aumenta la probabilità di trovare un Diamante di Cantoeterno con la Prospezione del Torio Abbagliante.', 65893),
(136584, 'itIT', 'Esperto della Frantumazione', '', 'Ottimizza le abilità di frantumazione, ottenendo +$ev1 $en1 quando si frantumano gemme per ogni punto in questa specializzazione.', 65893),
(136583, 'itIT', '', '', '+$ev1 $en1 quando si frantumano gemme.', 65893),
(136582, 'itIT', '', '', '+$ev1 $en1 quando si frantumano gemme.', 65893),
